from pathlib import Path

def write_text(path: str, content: str) -> str:
    target = Path(path).expanduser()
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')
    return str(target)

from pathlib import Path

def list_files(path: str = '.') -> list:
    target = Path(path).expanduser()
    return sorted(p.name for p in target.iterdir())

import re

def route(command: str):
    text = command.strip()
    m = re.match(r'create file (.+?) with (.+)$', text, re.I)
    if m:
        return {'action': 'file_write', 'path': m.group(1).strip(), 'content': m.group(2).strip()}
    m = re.match(r'open (.+)$', text, re.I)
    if m:
        return {'action': 'open_app', 'target': m.group(1).strip()}
    return {'action': 'chat', 'text': text}

