import re

def for_speech(text: str, limit: int = 220) -> str:
    cleaned = re.sub(r'\s+', ' ', text or '').strip()
    if len(cleaned) <= limit:
        return cleaned
    return cleaned[: limit - 1].rsplit(' ', 1)[0] + '.'
